#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>

#define K 3
#define TILE 16
#define REG 2
#define OUT_TILE (TILE * REG)
#define TILE_H (OUT_TILE + K - 1)
__global__ void conv2d_bf16_kernel(
    const __nv_bfloat16* __restrict__ input,
    const __nv_bfloat16* __restrict__ weight,
    __nv_bfloat16* __restrict__ output,
    int N, int C_in, int H, int W,
    int C_out, int H_out, int W_out,
    int tiles_w)
{
    extern __shared__ float s_mem[];
    float* s_weight = s_mem;                       // size = C_in*K*K
    float* s_input  = s_mem + C_in * K * K;         // size = C_in*TILE_H*TILE_H
    int n  = blockIdx.x;
    int oc = blockIdx.y;
    int tile_idx = blockIdx.z;
    int tile_row = tile_idx / tiles_w;
    int tile_col = tile_idx % tiles_w;
    int oh_base = tile_row * OUT_TILE;
    int ow_base = tile_col * OUT_TILE;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * blockDim.x + tx;
    int nthreads = blockDim.x * blockDim.y;
    int wsize = C_in * K * K;
    for (int i = tid; i < wsize; i += nthreads) {
        s_weight[i] = __bfloat162float(weight[oc * wsize + i]);
    }
    const __nv_bfloat16* input_n = input + (size_t)n * C_in * H * W;
    int input_tile_size = TILE_H * TILE_H;
    int total_input_elems = C_in * input_tile_size;
    for (int i = tid; i < total_input_elems; i += nthreads) {
        int c = i / input_tile_size;
        int rem = i % input_tile_size;
        int row = rem / TILE_H;
        int col = rem % TILE_H;
        int ih = oh_base + row;
        int iw = ow_base + col;
        float val = 0.0f;
        if (ih < H && iw < W) {
            val = __bfloat162float(input_n[(size_t)c * H * W + (size_t)ih * W + iw]);
        }
        s_input[i] = val;
    }
    __syncthreads();
    int oh0 = oh_base + ty;
    int ow0 = ow_base + tx;
    int oh1 = oh0 + TILE;
    int ow1 = ow0 + TILE;
    bool validRow0 = oh0 < H_out;
    bool validRow1 = oh1 < H_out;
    bool validCol0 = ow0 < W_out;
    bool validCol1 = ow1 < W_out;
    if (!validRow0 && !validRow1) return;
    if (!validCol0 && !validCol1) return;
    float sum00 = 0.0f, sum01 = 0.0f, sum10 = 0.0f, sum11 = 0.0f;
    for (int c = 0; c < C_in; c++) {
        const float* in_c = s_input + c * input_tile_size;
        const float* wgt_c = s_weight + c * K * K;
        #pragma unroll
        for (int kh = 0; kh < K; kh++) {
            #pragma unroll
            for (int kw = 0; kw < K; kw++) {
                float w = wgt_c[kh * K + kw];
                float v00 = in_c[(ty + kh) * TILE_H + (tx + kw)];
                float v01 = in_c[(ty + kh) * TILE_H + (tx + TILE + kw)];
                float v10 = in_c[(ty + TILE + kh) * TILE_H + (tx + kw)];
                float v11 = in_c[(ty + TILE + kh) * TILE_H + (tx + TILE + kw)];
                sum00 += v00 * w;
                sum01 += v01 * w;
                sum10 += v10 * w;
                sum11 += v11 * w;
            }
        }
    }
    size_t out_batch_offset = ((size_t)n * C_out + oc) * H_out * W_out;
    if (validRow0 && validCol0) {
        output[out_batch_offset + (size_t)oh0 * W_out + ow0] = __float2bfloat16(sum00);
    }
    if (validRow0 && validCol1) {
        output[out_batch_offset + (size_t)oh0 * W_out + ow1] = __float2bfloat16(sum01);
    }
    if (validRow1 && validCol0) {
        output[out_batch_offset + (size_t)oh1 * W_out + ow0] = __float2bfloat16(sum10);
    }
    if (validRow1 && validCol1) {
        output[out_batch_offset + (size_t)oh1 * W_out + ow1] = __float2bfloat16(sum11);
    }
